const j = $json.body || $json;
return {
  json: {
    ...j,
    content_key: 'content_' + Date.now(),
    owner_ref: j.owner_ref || 'system',
    title: j.title || 'New Phase 2 Idea',
    brief: j.brief || 'Autogenerated from N8N',
    state: 'idea'
  }
};

const baseUrl = ($env.SUPABASE_URL || '').trim().replace(/\/$/, '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const payload = {
  content_key: $json.content_key,
  owner_ref: $json.owner_ref,
  title: $json.title,
  brief: $json.brief
};
try {
  const res = await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase2_content_items`,
    method: 'POST',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}`, Prefer: 'return=representation' },
    body: payload,
    json: true
  });
  return { json: { ...$json, content_item: res[0], db_status: 'OK' } };
} catch (e) {
  return { json: { ...$json, db_status: 'ERROR', db_error: e.message } };
}

